#include <iostream>

int max(int num1, int num2) {
    int result;
    if (num1 > num2) {
        result = num1;
    } else {
        result = num2;
    }
    return result;
}

int main() {
    int i = 5;
    int j = 2;
    int k = max(i, j);
    std::cout << "The maximum between " << i << " and " << j << " is " << k << "\n";
    return 0;
}

#include <iostream>

// Void function with an early return guard
void printGrade(double score) {
    if (score < 0.0 || score > 100.0) {
        std::cout << "Invalid score\n";
        return;
    }

    if (score >= 90.0) {
        std::cout << "Grade: A\n";
    } else if (score >= 80.0) {
        std::cout << "Grade: B\n";
    } else if (score >= 70.0) {
        std::cout << "Grade: C\n";
    } else if (score >= 60.0) {
        std::cout << "Grade: D\n";
    } else {
        std::cout << "Grade: F\n";
    }
}

// Value-returning function returning char
char getGrade(double score) {
    if (score >= 90.0) return 'A';
    if (score >= 80.0) return 'B';
    if (score >= 70.0) return 'C';
    if (score >= 60.0) return 'D';
    return 'F';
}

int main() {
    double score1 = 78.5;
    double score2 = 105.0;

    std::cout << "The grade is " << getGrade(score1) << "\n";
    printGrade(score1);
    printGrade(score2);

    return 0;
}
